$$('[data-tab]').forEach(b=>b.onclick=()=>go(b.dataset.tab));$('householdBtn').onclick=household;$('filesBtn').onclick=filesDialog;$('shareBtn').onclick=shareDialog;$('demoBtn').onclick=()=>confirmDialog(t('Να ανοίξει το παράδειγμα;','Open the example?'),t('Το παράδειγμα θα αντικαταστήσει το τρέχον πλάνο και τις κινήσεις σου με ενδεικτικά δεδομένα. Πάρε πρώτα αντίγραφο ασφαλείας για να κρατήσεις όσα έχεις καταχωρίσει.','The example will replace your current budget and transactions with sample data. Back up first to keep your entries.'),()=>{clearShared();commit(E.demo(state.month));go('overview');$('message').textContent=t('Ενδεικτικά δεδομένα','Sample data');$('message').hidden=false;});
